// ─── File: MentorDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MentorDemo {

    private static final Logger log = Logger.getLogger(MentorDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Mentoring session: why money must not use double at " + BANK_NAME);

        // Rajesh's savings balance and Priya's current balance with a monthly rate.
        InterestInput rajesh = new InterestInput("SAV2001",
                new BigDecimal("1000000.00"), new BigDecimal("0.0933333"));
        InterestInput priya = new InterestInput("CUR3001",
                new BigDecimal("250000.00"), new BigDecimal("0.0333333"));

        WrongInterestCalculator wrong = new WrongInterestCalculator();
        CorrectInterestCalculator correct = new CorrectInterestCalculator(2, RoundingMode.HALF_EVEN);

        teach(rajesh, wrong, correct);
        teach(priya, wrong, correct);

        log.info("Lesson: double loses precision; BigDecimal with explicit rounding is correct for money.");
    }

    private static void teach(InterestInput in,
                              WrongInterestCalculator wrong,
                              CorrectInterestCalculator correct) {
        double wrongResult = wrong.interest(in.getBalance().doubleValue(),
                in.getRate().doubleValue());
        BigDecimal correctResult = correct.interest(in.getBalance(), in.getRate());
        log.warning(() -> in.getAccountId() + " double result (buggy): " + wrongResult);
        log.info(() -> in.getAccountId() + " BigDecimal result (correct): " + correctResult);
    }
}

// ─── Would be in model/InterestInput.java in a real project ───
class InterestInput {
    private final String accountId;
    private final BigDecimal balance;
    private final BigDecimal rate;

    InterestInput(String accountId, BigDecimal balance, BigDecimal rate) {
        this.accountId = accountId;
        this.balance = balance;
        this.rate = rate;
    }

    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    BigDecimal getRate() { return rate; }
}

// ─── Would be in calc/WrongInterestCalculator.java in a real project ───
// The junior's original approach. Looks fine, silently wrong for money.
class WrongInterestCalculator {
    double interest(double balance, double rate) {
        return balance * rate;
    }
}

// ─── Would be in calc/CorrectInterestCalculator.java in a real project ───
// The corrected approach taught during mentoring: BigDecimal + explicit rounding.
class CorrectInterestCalculator {
    private final int scale;
    private final RoundingMode roundingMode;

    CorrectInterestCalculator(int scale, RoundingMode roundingMode) {
        this.scale = scale;
        this.roundingMode = roundingMode;
    }

    BigDecimal interest(BigDecimal balance, BigDecimal rate) {
        return balance.multiply(rate).setScale(scale, roundingMode);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
